export function stepAt(steps,t){if(!steps.length)return null;let lo=0;let hi=steps.length-1;if(t<steps[0].t)return steps[0].step;while(lo<hi){const mid=lo+hi+1>>1;if(steps[mid].t<=t)lo=mid;else hi=mid-1}return steps[lo].step}export function frameOfStep(frameSteps,step){let lo=0;let hi=frameSteps.length-1;if(hi<0||step<=frameSteps[0])return 0;while(lo<hi){const mid=lo+hi+1>>1;if(frameSteps[mid]<=step)lo=mid;else hi=mid-1}return lo}export function viewsOfRecord(cameras,nameOf=k=>k){return cameras.map((c=>({id:`rec:${c.key}`,kind:"rec",label:nameOf(c.key),key:c.key})))}export function spanOf(steps){if(!steps.length)return{start:0,end:0};const n=steps.length;const last=n>1?steps[n-1].t-steps[n-2].t:.1;return{start:steps[0].t,end:steps[n-1].t+Math.max(0,last)}}const DRIFT_S=.2;export function createCameras(rec,{onTime:onTime=()=>{},onState:onState=()=>{},nameOf:nameOf}={}){const{start:start,end:end}=spanOf(rec.steps);const views=viewsOfRecord(rec.cameras,nameOf);const nodes=new Map;const urls=[];const players=[];rec.cameras.forEach(((cam,k)=>{const id=views[k].id;if(cam.video){const v=document.createElement("video");v.className="rp-video";Object.assign(v,{muted:true,playsInline:true,preload:"auto"});v.setAttribute("aria-label",`What the policy’s camera ${views[k].label} showed`);const url=URL.createObjectURL(new Blob([cam.video.bytes],{type:"video/mp4"}));urls.push(url);v.src=url;nodes.set(id,v);players.push({cam:cam,video:v})}else{const c=document.createElement("canvas");c.className="rp-video";c.width=cam.width;c.height=cam.height;c.setAttribute("role","img");c.setAttribute("aria-label",`What the policy’s camera ${views[k].label} showed`);nodes.set(id,c);players.push({cam:cam,canvas:c,drawn:-1})}}));let now=start;let on=false;let speed=1;let raf=0;let last=0;const clamp=t=>Math.min(end,Math.max(start,t));function draw(p,t){const fs=p.cam.rgb;let k=-1;for(let lo=0,hi=fs.length-1;lo<=hi;){const mid=lo+hi>>1;if(fs[mid].t<=t){k=mid;lo=mid+1}else hi=mid-1}k=Math.max(0,k);if(k===p.drawn||!fs.length)return;p.drawn=k;const{data:data}=fs[k];const img=new ImageData(p.cam.width,p.cam.height);for(let i=0,j=0;i<data.length;i+=3,j+=4){img.data[j]=data[i];img.data[j+1]=data[i+1];img.data[j+2]=data[i+2];img.data[j+3]=255}p.canvas.getContext("2d").putImageData(img,0,0)}function follow(hard){for(const p of players){if(p.canvas){draw(p,now);continue}const want=Math.max(0,now-p.cam.video.start);const len=Number.isFinite(p.video.duration)?p.video.duration:p.cam.video.duration;const to=Math.min(want,Math.max(0,len-.001));if(hard||Math.abs(p.video.currentTime-to)>DRIFT_S){try{p.video.currentTime=to}catch(_){}}}}for(const p of players){if(p.video)p.video.addEventListener("loadedmetadata",(()=>follow(true)))}const leading=()=>players.find((p=>p.video&&!p.video.paused&&!p.video.ended&&p.video.readyState>=2));function tick(ts){const lead=leading();if(lead)now=clamp(lead.cam.video.start+lead.video.currentTime);else if(ts!==undefined)now=clamp(now+Math.max(0,ts-last)/1e3*speed);if(ts!==undefined)last=ts;follow(false);onTime(now);if(now>=end){pause();return true}return false}function frame(ts){if(!tick(ts))raf=requestAnimationFrame(frame)}for(const p of players){if(p.video)p.video.addEventListener("timeupdate",(()=>{if(on)tick()}))}function play(){if(on)return;if(now>=end-1e-6)now=start;on=true;follow(true);for(const p of players){if(!p.video)continue;p.video.playbackRate=speed;p.video.play().catch((()=>{}))}last=performance.now();raf=requestAnimationFrame(frame);onState()}function pause(){if(!on)return;const lead=leading();if(lead)now=clamp(lead.cam.video.start+lead.video.currentTime);on=false;cancelAnimationFrame(raf);for(const p of players)if(p.video)p.video.pause();follow(true);onTime(now);onState()}function seek(t){now=clamp(t);follow(true);onTime(now)}function setSpeed(x){speed=Number(x)>0?Number(x):1;for(const p of players)if(p.video)p.video.playbackRate=speed}function mp4(id){const k=views.findIndex((v=>v.id===id));const cam=k>=0&&rec.cameras[k].video?rec.cameras[k]:rec.cameras.find((c=>c.video));return cam?{blob:new Blob([cam.video.bytes],{type:"video/mp4"}),key:cam.key}:null}function destroy(){pause();for(const u of urls)URL.revokeObjectURL(u);for(const n of nodes.values())n.remove()}follow(true);return{views:views,nodes:nodes,start:start,end:end,steps:rec.steps,time:()=>now,playing:()=>on,play:play,pause:pause,seek:seek,setSpeed:setSpeed,mp4:mp4,destroy:destroy}}